				$("#outputRef1").html((rowData.outputKey != null && rowData.outputKey != "") ? rowData.outputKey : "N/A");
				$("#outputRef2").html((rowData.lastSavedCode != null && rowData.lastSavedCode != "") ? rowData.lastSavedCode : "N/A");
				$("#outputReferenceDialog").modal("show");
			}
		}

functions.openErpLog:
function openErpLog(event, id){

			if(id != undefined && id != null){
				var rowData = $("#transmitDataTable").jqGrid('getRowData', id);
				if(rowData != undefined && rowData != null && rowData != ""){
					var retVal = $.ajax({
						url : "fetchPosIntLog",

						type : "POST",
						data : {
							extAppGlobalAppCode : rowData.extAppGlobalAppCode,
							extAppGlobalId 		: rowData.extAppGlobalId,
							extAppSubId 		: rowData.extAppSubId,
							documentType		: rowData.documentType,
							documentNo	 		: rowData.documentNo,
							clientId	 		: rowData.hdnClientId,
							orgId		 		: rowData.orgId,
							dbId		 		: rowData.dbId,
						},
						dataType : "json",
						async : false
					}).responseText;

					retVal = jQuery.parseJSON(retVal);
					let str = "";
					str = "Document Number";
					str += " : " + rowData.documentNo + " [ Exec Time : " + rowData.totalexecTime + "s ]";
					$("#headLabel").html(str);
					if(retVal != null && retVal != undefined && retVal.jsonMessage == "Success"){

						let log = retVal.customMap;

						if(log != undefined && log.requestJson != null && log.requestJson != "")
							editor.setValue(JSON.stringify(log.requestJson, null, '\t'), -1);
						else
							editor.setValue("");

						if(log != undefined && log.responseJson != null && log.responseJson != "")
							editor1.setValue(JSON.stringify(log.responseJson, null, '\t'), -1);
						else
							editor1.setValue("");
					}


					$("#requestResponseDialog").modal("show");
					return true;
				} else {
					window.parent.showAlert('Something Went Wrong');
					return false;
				}
			}
			else{
				window.parent.showAlert('Something Went Wrong');
				return false;
			}
		}

functions.openOrderLink:
function openOrderLink(orderNo, orderType, refrenceNo,txnType, event){
			if (window.parent){
				if(orderType == "RETURN"){
					if(txnType == "DSReturn"){
						window.parent.openScreen("Drop Ship Returns - "+orderNo,"dSReturnDetailDisplayBS?returnNo="+ orderNo, "fa fa-fw fa-list-ol");
					} else {
					if(refrenceNo != "")
					    window.parent.openScreen("Return Create/Edit-"+orderNo,"custReturnFetchDataBS?custRetCode="+ orderNo, "fa fa-fw fa-list-ol"); 
					else
						window.parent.openScreen("Return W/o Order  - "+orderNo,"custRetWithOutDisplay?custRetCode="+ orderNo, "fa fa-fw fa-list-ol");
					}
				}
				else if(orderType == "SO" || orderType == "INVOICE" || orderType == "CANCEL SO") {
					var retVal = $.ajax({
						url : "jsonOrderExits",

						type : "POST",		
						dataType : "json",
						async : false,
						data:{
							orderno:orderNo, 
							searchType : 1
						}
					}).responseText;

					retVal = jQuery.parseJSON(retVal);
					if(retVal.jsonMessage!=null && trimString(retVal.jsonMessage)!="") {
						alert('Error while searching for an order');
					}else if(retVal.orderMap!=null && retVal.orderMap!=""){
						debugger
						let dsOrderNo = ""; 
						$.each(retVal.orderMap, function(i, val) {
							if("WMS" == i.split("_")[0]) {
								orderNo = val;
							}
							else if("SP" == i.split("_")[0]){
								dsOrderNo = val;
							}
						});
						if(dsOrderNo != "")
							window.parent.openScreen("Order - "+dsOrderNo,"MarketOrderViewERP?orderNo="+dsOrderNo, "fa fa-fw fa-list-ol");
						else
							window.parent.openScreen("Order Create/Edit - "+orderNo, "orderMaintenanceBS?orderCode="+orderNo, "fa fa-fw fa-simplybuilt");
					}
				}
			  return false;
			}
		}

